import numpy as np

def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    scores = np.zeros(len(unvisited_nodes))
    for i, node in enumerate(unvisited_nodes):
        d_from_current = distance_matrix[current_node, node]
        # Compute variance of distances from this node to all other unvisited nodes (including destination)
        other_nodes = unvisited_nodes[unvisited_nodes != node]
        if len(other_nodes) > 0:
            dists_to_others = distance_matrix[node][other_nodes]
            var = np.var(dists_to_others)
        else:
            var = 0
        # Score: higher is better: exponential decay for distance, penalty for high variance
        scores[i] = np.exp(-d_from_current) - 0.3 * var
    return unvisited_nodes[np.argmax(scores)]
